package main

// upjet.go folds the facts read from Crossplane's Upjet provider
// (hack/upjet/provider-upjet-gcp.json, regenerated by the factory) onto our
// kinds and writes docs/coverage/upjet.{md,csv}: for each of our kinds and
// the Terraform resource Upjet serves for it, whether we take Upjet's
// references as references, whether the fields Upjet or the field's name
// hold secret are secrets here (the same rule as
// hack/discokind/secrets_test.go, which enforces it), the fields Upjet
// keeps out of late initialization, whether Upjet's maintainers tested
// the resource beside our own live ledger, and whether Upjet's
// hand-written examples set fields our spec or our fixtures do not.

import (
	"bytes"
	"encoding/json"
	"fmt"
	"os"
	"path/filepath"
	"regexp"
	"sort"
	"strconv"
	"strings"

	"gopkg.in/yaml.v3"
)

const upjetSlicePath = "hack/upjet/provider-upjet-gcp.json"

type upjetAt struct {
	Field string `json:"field"`
	At    string `json:"at"`
}

type upjetEntry struct {
	Ours struct {
		Service   string   `json:"service"`
		Resource  string   `json:"resource"`
		OursKinds []string `json:"oursKinds"`
	} `json:"ours"`
	Facts struct {
		Terraform    string `json:"terraform"`
		Group        string `json:"group"`
		Version      string `json:"version"`
		Kind         string `json:"kind"`
		Tested       bool   `json:"tested"`
		ExternalName struct {
			Style    string `json:"style"`
			Template string `json:"template"`
			At       string `json:"at"`
		} `json:"externalName"`
		References []struct {
			Field  string `json:"field"`
			Target string `json:"target"`
			At     string `json:"at"`
		} `json:"references"`
		LateInitIgnored []upjetAt `json:"lateInitIgnored"`
		SchemaOverrides []struct {
			Field    string `json:"field"`
			Property string `json:"property"`
			Value    string `json:"value"`
			At       string `json:"at"`
		} `json:"schemaOverrides"`
		MovedToStatus []upjetAt `json:"movedToStatus"`
		CustomCode    []struct {
			What string `json:"what"`
			At   string `json:"at"`
		} `json:"customCode"`
		Examples []struct {
			At     string   `json:"at"`
			Origin string   `json:"origin"`
			Fields []string `json:"fields"`
		} `json:"examples"`
	} `json:"facts"`
	TargetsOurs map[string][]string `json:"targetsOurs"`
}

type upjetSlice struct {
	Provider struct {
		Repo   string `json:"repo"`
		Tag    string `json:"tag"`
		Commit string `json:"commit"`
	} `json:"provider"`
	Counts  map[string]int `json:"counts"`
	Entries []upjetEntry   `json:"entries"`
	NoUpjet []string       `json:"noUpjet"`
}

// discoKind is the part of hack/discokind/kinds.yaml read here.
type discoKind struct {
	Kind          string            `yaml:"kind"`
	Terraform     string            `yaml:"terraform"`
	SecretWaivers map[string]string `yaml:"secretWaivers"`
}

// upjetSecretNames are the field names held secret whatever the API: the
// list in hack/discokind/secrets_test.go.
var upjetSecretNames = map[string]bool{
	"password": true, "rawkey": true, "rsaencryptedkey": true, "sharedsecret": true,
	"privatekey": true, "clientsecret": true, "apikey": true, "secretkey": true,
	"accesstoken": true, "refreshtoken": true, "passphrase": true,
}

// upjetPair is one of our kinds against one Terraform resource Upjet
// serves for the same API resource.
type upjetPair struct {
	kind    string
	e       *upjetEntry
	join    string // terraform (kinds.yaml), name (same name), resource (same API resource only)
	counted bool   // the kind's own resource: a terraform or name join, or the only kind of join it has
	live    string

	refs                                   int
	refRef, refPlain, refServed, refAbsent []string
	secrets                                []upjetSecret
	lateInit                               []string // field (here or absent)
	hand                                   int
	exUnmapped, exNotInFixtures            []string
}

type upjetSecret struct {
	path, why, state string // state: secret, secretFrom, waived, plain
}

func (p *upjetPair) secretsPlain() []upjetSecret {
	var out []upjetSecret
	for _, s := range p.secrets {
		if s.state == "waived" || s.state == "plain" {
			out = append(out, s)
		}
	}
	return out
}

func upjetWriteOnlyBase(f string) string {
	for _, suf := range []string{"_wo_version", "_wo"} {
		if strings.HasSuffix(f, suf) {
			return strings.TrimSuffix(f, suf)
		}
	}
	return f
}

// upjetLink is a link to where Upjet's source says a fact, at the commit.
func upjetLink(s *upjetSlice, at string) string {
	file, line, _ := strings.Cut(at, ":")
	u := "https://github.com/" + s.Provider.Repo + "/blob/" + s.Provider.Commit + "/" + file
	if line != "" {
		u += "#L" + line
	}
	return "[`" + at + "`](" + u + ")"
}

// loadLedger reads docs/live-runs.md's ledger: kind -> PASS if any live
// run passed, else the latest Live cell.
func loadLedger(repo string, kinds map[string]bool) (map[string]string, error) {
	b, err := os.ReadFile(filepath.Join(repo, "docs", "live-runs.md"))
	if err != nil {
		return nil, err
	}
	_, ledger, ok := strings.Cut(string(b), "\n## Ledger\n")
	if !ok {
		return nil, fmt.Errorf("docs/live-runs.md has no Ledger section")
	}
	word := regexp.MustCompile(`[A-Z][A-Za-z0-9]+`)
	out := map[string]string{}
	for _, l := range strings.Split(ledger, "\n") {
		if strings.HasPrefix(l, "## ") {
			break
		}
		cells := strings.Split(l, "|")
		if len(cells) < 7 || !strings.HasPrefix(l, "| 20") {
			continue
		}
		live := strings.TrimSpace(cells[5])
		if f := strings.FieldsFunc(live, func(r rune) bool { return r == ' ' || r == ',' || r == ':' || r == ';' || r == '(' }); len(f) > 0 {
			live = strings.Trim(f[0], "`*")
		}
		for _, k := range word.FindAllString(cells[3], -1) {
			if kinds[k] && out[k] != "PASS" {
				out[k] = live
			}
		}
	}
	return out, nil
}

// fixtureFields are the top-level spec fields our discokind fixtures of a
// kind set (every fixture set), as norm()ed names.
func fixtureFields(repo, kind string) map[string]bool {
	var files []string
	for _, pat := range []string{"*.yaml", "*/*.yaml"} {
		fs, _ := filepath.Glob(filepath.Join(repo, "pkg/controller/direct/*/discokindtest/testdata/discokind", kind, pat))
		files = append(files, fs...)
	}
	out := map[string]bool{}
	for _, f := range files {
		b, err := os.ReadFile(f)
		if err != nil {
			continue
		}
		var obj struct {
			Spec map[string]any `yaml:"spec"`
		}
		if yaml.Unmarshal(b, &obj) != nil {
			continue
		}
		for k := range obj.Spec {
			out[norm(strings.TrimSuffix(k, "Ref"))] = true
		}
	}
	return out
}

func buildUpjet(repo string, m *model) (*upjetSlice, []*upjetPair, error) {
	b, err := os.ReadFile(filepath.Join(repo, upjetSlicePath))
	if err != nil {
		return nil, nil, err
	}
	s := &upjetSlice{}
	if err := json.Unmarshal(b, s); err != nil {
		return nil, nil, fmt.Errorf("%s: %w", upjetSlicePath, err)
	}
	kb, err := os.ReadFile(filepath.Join(repo, "hack", "discokind", "kinds.yaml"))
	if err != nil {
		return nil, nil, err
	}
	var dks []discoKind
	if err := yaml.Unmarshal(kb, &dks); err != nil {
		return nil, nil, fmt.Errorf("hack/discokind/kinds.yaml: %w", err)
	}
	disco := map[string]*discoKind{}
	for i := range dks {
		disco[dks[i].Kind] = &dks[i]
	}
	crds := map[string]*CRD{}
	isKind := map[string]bool{}
	for _, c := range m.oursCRDs {
		crds[c.Kind] = c
		isKind[c.Kind] = true
	}
	ledger, err := loadLedger(repo, isKind)
	if err != nil {
		return nil, nil, err
	}

	seen := map[string]bool{}
	var pairs []*upjetPair
	strong := map[string]bool{}
	for i := range s.Entries {
		e := &s.Entries[i]
		for _, k := range e.Ours.OursKinds {
			if crds[k] == nil || seen[k+" "+e.Facts.Terraform] {
				continue
			}
			seen[k+" "+e.Facts.Terraform] = true
			join := "resource"
			switch {
			case disco[k] != nil && disco[k].Terraform == e.Facts.Terraform:
				join = "terraform"
			case norm(strings.TrimPrefix(e.Facts.Terraform, "google_")) == strings.ToLower(k):
				join = "name"
			}
			if join != "resource" {
				strong[k] = true
			}
			pairs = append(pairs, &upjetPair{kind: k, e: e, join: join})
		}
	}
	for _, p := range pairs {
		p.counted = p.join != "resource" || !strong[p.kind]
		p.live = ledger[p.kind]
		if p.live == "" {
			p.live = "no row"
		}
		c := crds[p.kind]
		byKey := map[string]*CPath{}
		for i := range c.Paths {
			cp := &c.Paths[i]
			if prev := byKey[cp.key]; prev == nil || cp.Ref {
				byKey[cp.key] = cp
			}
		}
		// References.
		for _, r := range p.e.Facts.References {
			p.refs++
			label := r.Field + " → " + r.Target
			cp := byKey[attrKey(r.Field)]
			switch {
			case cp == nil:
				p.refAbsent = append(p.refAbsent, label)
			case cp.Ref:
				p.refRef = append(p.refRef, label)
			default:
				p.refPlain = append(p.refPlain, label)
				if len(p.e.TargetsOurs[r.Target]) > 0 {
					p.refServed = append(p.refServed, label+" ("+strings.Join(p.e.TargetsOurs[r.Target], ", ")+")")
				}
			}
		}
		// Secrets: by name, and Upjet's Sensitive and write-only fields.
		var waivers map[string]string
		if d := disco[p.kind]; d != nil {
			waivers = d.SecretWaivers
		}
		upjet := map[string]string{}
		if p.join != "resource" {
			for _, o := range p.e.Facts.SchemaOverrides {
				if o.Property == "Sensitive" && o.Value == "true" {
					upjet[attrKey(upjetWriteOnlyBase(o.Field))] = "Upjet Sensitive " + upjetLink(s, o.At)
				}
			}
			for _, mv := range p.e.Facts.MovedToStatus {
				if b := upjetWriteOnlyBase(mv.Field); b != mv.Field {
					upjet[attrKey(b)] = "Upjet write-only `" + mv.Field + "` " + upjetLink(s, mv.At)
				}
			}
		}
		secretSeen := map[string]bool{}
		for i := range c.Paths {
			cp := &c.Paths[i]
			segs := strings.Split(markers.ReplaceAllString(cp.Path, ""), ".")
			leaf := segs[len(segs)-1]
			why := ""
			switch {
			case upjetSecretNames[strings.ToLower(leaf)]:
				why = "named `" + leaf + "`"
			case upjet[cp.key] != "":
				why = upjet[cp.key]
			default:
				continue
			}
			if w := upjet[cp.key]; w != "" && !strings.HasPrefix(why, "Upjet") {
				why += "; " + w
			}
			if secretSeen[cp.Path] {
				continue
			}
			secretSeen[cp.Path] = true
			state := "plain"
			switch {
			case cp.Secret:
				state = "secret"
			case byKey[cp.key+"from.secretkeyref.key"] != nil || byKey[cp.key+"from.secretkeyref.name"] != nil:
				state = "secretFrom"
			case waivers[cp.Path] != "":
				state = "waived"
			}
			p.secrets = append(p.secrets, upjetSecret{cp.Path, why, state})
		}
		// Late initialization.
		for _, li := range p.e.Facts.LateInitIgnored {
			k := attrKey(li.Field)
			here := "absent here"
			for key := range byKey {
				if key == k || strings.HasPrefix(key, k+".") {
					here = "here"
					break
				}
			}
			p.lateInit = append(p.lateInit, li.Field+" ("+here+")")
		}
		// Hand-written examples, for the kind's own resource only: a field
		// no path of our spec matches by name (the shortest such path), and
		// a top-level field none of our discokind fixtures sets.
		var fx map[string]bool
		if disco[p.kind] != nil {
			fx = fixtureFields(repo, p.kind)
		}
		hasKey := func(k string) bool {
			for key := range byKey {
				if key == k || strings.HasPrefix(key, k+".") {
					return true
				}
			}
			return false
		}
		exSeen := map[string]bool{}
		var exFields []string
		for _, ex := range p.e.Facts.Examples {
			if ex.Origin != "hand" {
				continue
			}
			p.hand++
			for _, f := range ex.Fields {
				if !exSeen[f] {
					exSeen[f] = true
					exFields = append(exFields, f)
				}
			}
		}
		sort.Strings(exFields)
		if p.join != "resource" {
			for _, f := range exFields {
				k := attrKey(f)
				if k == "project" || k == "name" {
					continue
				}
				under := false
				for _, u := range p.exUnmapped {
					if strings.HasPrefix(f, u+".") {
						under = true
					}
				}
				switch {
				case under:
				case !hasKey(k):
					p.exUnmapped = append(p.exUnmapped, f)
				case fx != nil && !strings.Contains(f, ".") && !fx[norm(f)] && !fx[singular(norm(f))]:
					p.exNotInFixtures = append(p.exNotInFixtures, f)
				}
			}
		}
		sort.Strings(p.exUnmapped)
		sort.Strings(p.exNotInFixtures)
	}
	sort.Slice(pairs, func(i, j int) bool {
		if pairs[i].kind != pairs[j].kind {
			return pairs[i].kind < pairs[j].kind
		}
		return pairs[i].e.Facts.Terraform < pairs[j].e.Facts.Terraform
	})
	return s, pairs, nil
}

func upjetCSV(pairs []*upjetPair) []byte {
	rows := [][]string{{"kind", "terraform", "join", "counted", "upjet_kind", "upjet_tested", "live", "references", "references_as_ref", "references_plain", "references_plain_target_here", "references_absent", "secret_fields", "secret_fields_plain", "id_format", "late_init_ignored", "hand_examples", "example_fields_unmapped", "example_fields_not_in_fixtures", "custom_code"}}
	for _, p := range pairs {
		f := p.e.Facts
		var sec, plain []string
		for _, s := range p.secrets {
			sec = append(sec, s.path+"="+s.state)
		}
		for _, s := range p.secretsPlain() {
			plain = append(plain, s.path)
		}
		id := f.ExternalName.Template
		if id == "" {
			id = f.ExternalName.Style
		}
		var cc []string
		for _, c := range f.CustomCode {
			cc = append(cc, c.What)
		}
		uk := ""
		if f.Kind != "" {
			uk = f.Group + "/" + f.Version + "/" + f.Kind
		}
		rows = append(rows, []string{p.kind, f.Terraform, p.join, b2s(p.counted), uk, b2s(f.Tested), p.live,
			strconv.Itoa(p.refs), strconv.Itoa(len(p.refRef)), strconv.Itoa(len(p.refPlain)), strconv.Itoa(len(p.refServed)), strconv.Itoa(len(p.refAbsent)),
			strings.Join(sec, "; "), strings.Join(plain, "; "), id, strings.Join(p.lateInit, "; "), strconv.Itoa(p.hand),
			strings.Join(p.exUnmapped, "; "), strings.Join(p.exNotInFixtures, "; "), strings.Join(cc, "; ")})
	}
	return csvBytes(rows)
}

// upjetTotals are the after-numbers over the counted pairs.
type upjetTotals struct {
	kinds, pairs, alsoPairs, untested, untestedNoLive                     int
	refs, refRef, refPlain, refServed, refAbsent                          int
	secrets, secretOK, secretWaived, secretPlain                          int
	lateInit, hand, exUnmapped, exNotInFixtures, discoKinds, discoMatched int
}

func upjetTotalsOf(pairs []*upjetPair, discoTF map[string]bool) upjetTotals {
	var t upjetTotals
	kinds := map[string]bool{}
	for _, p := range pairs {
		if !p.counted {
			t.alsoPairs++
			continue
		}
		t.pairs++
		kinds[p.kind] = true
		if !p.e.Facts.Tested {
			t.untested++
			if p.live != "PASS" {
				t.untestedNoLive++
			}
		}
		t.refs += p.refs
		t.refRef += len(p.refRef)
		t.refPlain += len(p.refPlain)
		t.refServed += len(p.refServed)
		t.refAbsent += len(p.refAbsent)
		for _, s := range p.secrets {
			t.secrets++
			switch s.state {
			case "secret", "secretFrom":
				t.secretOK++
			case "waived":
				t.secretWaived++
			default:
				t.secretPlain++
			}
		}
		t.lateInit += len(p.lateInit)
		t.hand += p.hand
		t.exUnmapped += len(p.exUnmapped)
		t.exNotInFixtures += len(p.exNotInFixtures)
		if p.join == "terraform" {
			t.discoMatched++
		}
	}
	t.kinds = len(kinds)
	t.discoKinds = len(discoTF)
	return t
}

func upjetMD(s *upjetSlice, pairs []*upjetPair, discoTF map[string]bool) string {
	t := upjetTotalsOf(pairs, discoTF)
	var b bytes.Buffer
	short := s.Provider.Commit
	if len(short) > 12 {
		short = short[:12]
	}
	b.WriteString("# Our kinds against Crossplane's Upjet provider\n\n")
	fmt.Fprintf(&b, "Generated by `hack/coverage` (`task coverage`) from [`%s`](../../%s): the facts the factory reads from [%s](https://github.com/%s) %s (`%s`), joined onto our API resources. Every row is in [`upjet.csv`](upjet.csv). Nothing here runs a Crossplane provider.\n\n", upjetSlicePath, upjetSlicePath, s.Provider.Repo, s.Provider.Repo, s.Provider.Tag, short)
	b.WriteString("Each of our kinds is set against each Terraform resource Upjet serves for the same API resource. The **join** says how the two meet: `terraform` (the kind's `terraform:` in `hack/discokind/kinds.yaml`), `name` (the kind and the resource have the same name: `SQLUser`, `google_sql_user`) or `resource` (only the API resource). A kind with a `terraform` or `name` join is counted on those alone; its `resource` joins are listed as related and not counted.\n\n")
	b.WriteString("## Numbers\n\n")
	b.WriteString("| Before: the slice as delivered | |\n| --- | ---: |\n")
	for _, k := range []string{"ours", "matched", "references", "referencesOur", "handExamples", "notTested"} {
		fmt.Fprintf(&b, "| `%s` | %d |\n", k, s.Counts[k])
	}
	fmt.Fprintf(&b, "| entries / API resources with no Upjet resource | %d / %d |\n\n", len(s.Entries), len(s.NoUpjet))
	b.WriteString("| After: folded onto our kinds | |\n| --- | ---: |\n")
	fmt.Fprintf(&b, "| Our kinds with an Upjet resource | %d |\n", t.kinds)
	fmt.Fprintf(&b, "| Pairs counted (kind × Terraform resource) / related, not counted | %d / %d |\n", t.pairs, t.alsoPairs)
	fmt.Fprintf(&b, "| `hack/discokind` kinds joined by their `terraform:` / with a `terraform:` | %d / %d |\n", t.discoMatched, t.discoKinds)
	fmt.Fprintf(&b, "| Upjet references on counted pairs | %d |\n", t.refs)
	fmt.Fprintf(&b, "| … a reference here too (`*Ref`) | %d |\n", t.refRef)
	fmt.Fprintf(&b, "| … a plain string here | %d |\n", t.refPlain)
	fmt.Fprintf(&b, "| … a plain string here, to a kind served here (a gap) | %d |\n", t.refServed)
	fmt.Fprintf(&b, "| … a field our spec does not have | %d |\n", t.refAbsent)
	fmt.Fprintf(&b, "| Secret fields (by name, or Upjet Sensitive or write-only) | %d |\n", t.secrets)
	fmt.Fprintf(&b, "| … a secret here (value/valueFrom, or `<field>From.secretKeyRef`) | %d |\n", t.secretOK)
	fmt.Fprintf(&b, "| … plain, waived in `kinds.yaml` (open) | %d |\n", t.secretWaived)
	fmt.Fprintf(&b, "| … plain, not waived | %d |\n", t.secretPlain)
	fmt.Fprintf(&b, "| Pairs Upjet's maintainers did not test / … and no live PASS here | %d / %d |\n", t.untested, t.untestedNoLive)
	fmt.Fprintf(&b, "| Fields Upjet keeps out of late initialization | %d |\n", t.lateInit)
	fmt.Fprintf(&b, "| Hand-written Upjet examples / their fields no field of ours matches by name / fields our fixtures never set | %d / %d / %d |\n\n", t.hand, t.exUnmapped, t.exNotInFixtures)

	// Ranked gaps.
	type gap struct {
		kind  string
		score int
		what  []string
	}
	gaps := map[string]*gap{}
	add := func(k string, score int, what string) {
		g := gaps[k]
		if g == nil {
			g = &gap{kind: k}
			gaps[k] = g
		}
		g.score += score
		g.what = append(g.what, what)
	}
	for _, p := range pairs {
		if !p.counted {
			continue
		}
		for _, sp := range p.secretsPlain() {
			add(p.kind, 5, "secret `"+sp.path+"` is plain ("+sp.state+")")
		}
		if n := len(p.refServed); n > 0 {
			add(p.kind, 2*n, fmt.Sprintf("%d reference(s) to kinds served here taken as plain strings (`%s`)", n, p.e.Facts.Terraform))
		}
		if !p.e.Facts.Tested && p.live != "PASS" {
			add(p.kind, 1, "`"+p.e.Facts.Terraform+"` untested by Upjet and no live PASS here")
		}
		if n := len(p.exUnmapped); n > 0 {
			add(p.kind, n, "Upjet example fields no field of our spec matches by name: `"+strings.Join(p.exUnmapped, "`, `")+"`")
		}
	}
	var gl []*gap
	for _, g := range gaps {
		gl = append(gl, g)
	}
	sort.Slice(gl, func(i, j int) bool {
		if gl[i].score != gl[j].score {
			return gl[i].score > gl[j].score
		}
		return gl[i].kind < gl[j].kind
	})
	b.WriteString("## Gaps, ranked\n\n")
	b.WriteString("Score: 5 a plain secret field, 2 a reference to a kind served here taken as a plain string, 1 a resource neither Upjet nor our live runs tested, 1 an Upjet example field no field of our spec matches by name. The ten highest:\n\n")
	b.WriteString("| # | Kind | Score | What |\n| ---: | --- | ---: | --- |\n")
	for i, g := range gl {
		if i == 10 {
			break
		}
		fmt.Fprintf(&b, "| %d | `%s` | %d | %s |\n", i+1, g.kind, g.score, strings.Join(g.what, "; "))
	}
	b.WriteString("\n")

	// Disagreements.
	b.WriteString("## Where we and Upjet disagree\n\n")
	b.WriteString("### Secrets\n\n")
	b.WriteString("`hack/discokind/secrets_test.go` fails on a plain secret field that `kinds.yaml` does not waive; the waivers are open work (`docs/design.md` section 7).\n\n")
	b.WriteString("| Kind | Field | Why it is secret | Here |\n| --- | --- | --- | --- |\n")
	for _, p := range pairs {
		if !p.counted {
			continue
		}
		for _, sc := range p.secrets {
			fmt.Fprintf(&b, "| `%s` | `%s` | %s | %s |\n", p.kind, sc.path, sc.why, sc.state)
		}
	}
	b.WriteString("\n### References taken as plain strings\n\n")
	b.WriteString("Upjet resolves these fields from another managed resource; our spec takes a string, though a kind here serves the target. A `hack/discokind` kind takes only its parent as a reference, so its rows are expected until the generator learns references.\n\n")
	b.WriteString("| Kind | Terraform | Field → target (kinds here) |\n| --- | --- | --- |\n")
	for _, p := range pairs {
		if !p.counted {
			continue
		}
		for _, r := range p.refServed {
			fmt.Fprintf(&b, "| `%s` | `%s` | `%s` |\n", p.kind, p.e.Facts.Terraform, r)
		}
	}
	b.WriteString("\n### Not tested by Upjet\n\n")
	b.WriteString("Live here is the kind's best result in `docs/live-runs.md`'s ledger, whichever of its resources ran; a `resource` join is a related Terraform resource, not the kind's own.\n\n")
	b.WriteString("| Kind | Terraform | Join | Live here |\n| --- | --- | --- | --- |\n")
	for _, p := range pairs {
		if p.counted && !p.e.Facts.Tested {
			fmt.Fprintf(&b, "| `%s` | `%s` | %s | %s |\n", p.kind, p.e.Facts.Terraform, p.join, p.live)
		}
	}
	b.WriteString("\n### Late initialization\n\n")
	b.WriteString("Fields Upjet keeps out of late initialization: the API fills them, and copying them back into the spec fights the user. Our controllers compare only what the spec sets, so these are for a reviewer to look at, not failures.\n\n")
	b.WriteString("| Kind | Terraform | Fields |\n| --- | --- | --- |\n")
	for _, p := range pairs {
		if p.counted && len(p.lateInit) > 0 {
			fmt.Fprintf(&b, "| `%s` | `%s` | %s |\n", p.kind, p.e.Facts.Terraform, strings.Join(p.lateInit, "; "))
		}
	}
	b.WriteString("\n### Example fields\n\n")
	b.WriteString("Fields Upjet's hand-written examples set (for the kind's own resource) that no field of our spec matches by name, which is often a different name or shape rather than a missing field; and, for `hack/discokind` kinds, top-level fields none of our fixtures set.\n\n")
	b.WriteString("| Kind | Terraform | Not in our spec | Not in our fixtures |\n| --- | --- | --- | --- |\n")
	for _, p := range pairs {
		if p.counted && len(p.exUnmapped)+len(p.exNotInFixtures) > 0 {
			fmt.Fprintf(&b, "| `%s` | `%s` | %s | %s |\n", p.kind, p.e.Facts.Terraform, upjetCodes(p.exUnmapped), upjetCodes(p.exNotInFixtures))
		}
	}
	b.WriteString("\n## Every pair\n\n")
	b.WriteString("| Kind | Terraform | Join | Upjet tested | Live | References (ref / plain / absent) | Secrets | Hand examples |\n| --- | --- | --- | --- | --- | --- | --- | ---: |\n")
	for _, p := range pairs {
		tf := "`" + p.e.Facts.Terraform + "`"
		if !p.counted {
			tf += " (related)"
		}
		sec := "none"
		if len(p.secrets) > 0 {
			var l []string
			for _, s := range p.secrets {
				l = append(l, s.state)
			}
			sec = strings.Join(l, ", ")
		}
		fmt.Fprintf(&b, "| `%s` | %s | %s | %s | %s | %d (%d / %d / %d) | %s | %d |\n", p.kind, tf, p.join, b2s(p.e.Facts.Tested), p.live, p.refs, len(p.refRef), len(p.refPlain), len(p.refAbsent), sec, p.hand)
	}
	return b.String()
}

func upjetCodes(l []string) string {
	if len(l) == 0 {
		return ""
	}
	return "`" + strings.Join(l, "`, `") + "`"
}

// upjetFiles writes docs/coverage/upjet.{md,csv} and returns a sentence
// for the README.
func upjetFiles(repo string, m *model, files map[string][]byte) (string, error) {
	s, pairs, err := buildUpjet(repo, m)
	if err != nil {
		return "", err
	}
	kb, err := os.ReadFile(filepath.Join(repo, "hack", "discokind", "kinds.yaml"))
	if err != nil {
		return "", err
	}
	var dks []discoKind
	if err := yaml.Unmarshal(kb, &dks); err != nil {
		return "", err
	}
	discoTF := map[string]bool{}
	for _, d := range dks {
		if d.Terraform != "" {
			discoTF[d.Kind] = true
		}
	}
	files["docs/coverage/upjet.csv"] = upjetCSV(pairs)
	files["docs/coverage/upjet.md"] = []byte(upjetMD(s, pairs, discoTF))
	t := upjetTotalsOf(pairs, discoTF)
	return fmt.Sprintf("Against Crossplane's Upjet provider (%s): %d of our kinds have an Upjet resource; of the %d references Upjet resolves on them, %d are references here and %d are plain strings to a kind served here; %d secret fields are secrets here and %d are open ([`upjet.md`](docs/coverage/upjet.md)).", s.Provider.Tag, t.kinds, t.refs, t.refRef, t.refServed, t.secretOK, t.secretWaived+t.secretPlain), nil
}
